'use strict';

// MODULES //

var isCollection = require( '@stdlib/assert-is-collection' );
var isArrayBuffer = require( '@stdlib/assert-is-arraybuffer' );
var isNonNegativeIntegerArray = require( '@stdlib/assert-is-nonnegative-integer-array' ).primitives;
var isNonNegativeInteger = require( '@stdlib/assert-is-nonnegative-integer' ).isPrimitive;
var isIntegerArray = require( '@stdlib/assert-is-integer-array' ).primitives;
var isOrder = require( '@stdlib/ndarray-base-assert-is-order' );
var isDataType = require( '@stdlib/ndarray-base-assert-is-data-type' );
var isGenericDataType = require( '@stdlib/ndarray-base-assert-is-generic-data-type' );
var isBinaryDataType = require( '@stdlib/ndarray-base-assert-is-binary-data-type' );
var isStructDataType = require( '@stdlib/ndarray-base-assert-is-struct-data-type' );
var isBufferLengthCompatible = require( '@stdlib/ndarray-base-assert-is-buffer-length-compatible' );
var numel = require( '@stdlib/ndarray-base-numel' );
var minmaxViewBufferIndex = require( '@stdlib/ndarray-base-minmax-view-buffer-index' );
var strides2offset = require( '@stdlib/ndarray-base-strides2offset' );
var ndarray = require( '@stdlib/ndarray-ctor' );
var arraybuffer2buffer = require( '@stdlib/buffer-from-arraybuffer' );
var typedarray = require( '@stdlib/array-typed' );
var structFactory = require( '@stdlib/array-struct-factory' );
var format = require( '@stdlib/string-format' );


// MAIN //

/**
* Creates an ndarray from an ArrayBuffer.
*
* @param {*} dtype - data type
* @param {ArrayBuffer} buffer - ArrayBuffer
* @param {NonNegativeIntegerArray} shape - array shape
* @param {IntegerArray} strides - array strides
* @param {NonNegativeInteger} byteOffset - byte offset
* @param {string} order - memory layout (either row-major or column-major)
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
* @param {string} [options.mode='throw'] - specifies how to handle indices which exceed ndarray dimensions
* @param {StringArray} [options.submode=[options.mode]] - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
* @throws {TypeError} `dtype` argument must be a supported ndarray data type
* @throws {TypeError} `buffer` argument must be an ArrayBuffer
* @throws {TypeError} `shape` argument must be an array-like object containing nonnegative integers
* @throws {TypeError} `strides` argument must be an array-like object containing integers
* @throws {Error} `strides` argument length must equal the number of dimensions (except for zero-dimensional arrays; in which case, the `strides` argument length must be equal to `1`)
* @throws {Error} for zero-dimensional ndarrays, the `strides` argument must contain a single element equal to `0`
* @throws {TypeError} `byteOffset` argument must be a nonnegative integer
* @throws {TypeError} `order` argument must be a supported ndarray order
* @throws {Error} `buffer` argument must be compatible with specified meta data
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @throws {RangeError} too many dimensions
* @returns {ndarray} ndarray
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 4
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float32', buf, [ 4, 2 ], [ 2, 1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 8
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2 ], [ -2, -1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 4
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2 ], [ -1, -2 ], 0, 'column-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 4
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 64 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2, 2 ], [ 2, -4, 1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 8
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 1, 2 ], [ -2, -1 ], 8, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 2
*/
function arraybuffer2ndarray( dtype, buffer, shape, strides, byteOffset, order, options ) { // eslint-disable-line max-len
	var offset;
	var ndims;
	var buf;
	var idx;
	var len;
	var N;

	if ( !isDataType( dtype ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a supported ndarray data type. Value: `%s`.', dtype ) );
	}
	if ( isGenericDataType( dtype ) ) {
		throw new TypeError( format( 'invalid argument. ArrayBuffer is incompatible with the specified data type. Value: `%s`.', dtype ) );
	}
	if ( !isArrayBuffer( buffer ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an ArrayBuffer. Value: `%s`.', buffer ) );
	}
	if ( !isNonNegativeIntegerArray( shape ) ) {
		if ( !isCollection( shape ) || shape.length > 0 ) {
			throw new TypeError( format( 'invalid argument. Third argument must be an array-like object containing nonnegative integers. Value: `%s`.', shape ) );
		}
	}
	ndims = shape.length;
	if ( !isIntegerArray( strides ) ) {
		throw new TypeError( format( 'invalid argument. Fourth argument must be an array-like object containing integers. Value: `%s`.', strides ) );
	}
	if ( ndims > 0 ) {
		if ( strides.length !== ndims ) {
			throw new RangeError( format( 'invalid argument. Fourth argument length must match the number of dimensions. Expected number of dimensions: `%u`. Strides length: `%u`.', ndims, strides.length ) );
		}
	} else if ( strides.length !== 1 ) {
		throw new RangeError( 'invalid argument. Fourth argument length must be equal to 1 when creating a zero-dimensional ndarray.' );
	} else if ( strides[ 0 ] !== 0 ) {
		throw new RangeError( format( 'invalid argument. Fourth argument must contain a single element equal to 0. Value: `%d`.', strides[ 0 ] ) );
	}
	if ( !isNonNegativeInteger( byteOffset ) ) {
		throw new TypeError( format( 'invalid argument. Fifth argument must be a nonnegative integer. Value: `%s`.', byteOffset ) );
	}
	if ( !isOrder( order ) ) {
		throw new TypeError( format( 'invalid argument. Sixth argument must be a supported order. Value: `%s`.', order ) );
	}
	// Compute the number of underlying elements across which the ndarray view will span:
	offset = strides2offset( shape, strides );
	idx = minmaxViewBufferIndex( shape, strides, offset );
	len = numel( shape );
	N = ( len === 0 ) ? 0 : idx[ 1 ] - idx[ 0 ] + 1;

	// Create the underlying ndarray buffer:
	if ( isBinaryDataType( dtype ) ) {
		buf = arraybuffer2buffer( buffer, byteOffset, N );
	} else if ( isStructDataType( dtype ) ) {
		buf = structFactory( dtype )( buffer, byteOffset, N );
	} else {
		buf = typedarray( buffer, byteOffset, N, dtype );
	}
	if ( ndims > 0 && len > 0 && !isBufferLengthCompatible( buf.length, shape, strides, offset ) ) { // eslint-disable-line max-len
		throw new Error( 'invalid arguments. Input buffer is incompatible with the specified meta data. Ensure that the offset is valid with regard to the strides array and that the buffer has enough elements to satisfy the desired array shape.' );
	}
	// Return a new ndarray instance:
	if ( arguments.length > 6 ) {
		return new ndarray( dtype, buf, shape, strides, offset, order, options ); // eslint-disable-line max-len
	}
	return new ndarray( dtype, buf, shape, strides, offset, order );
}


// EXPORTS //

module.exports = arraybuffer2ndarray;
