'use strict';

/**
* Create an ndarray from an ArrayBuffer.
*
* @module @stdlib/ndarray-from-arraybuffer
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var arraybuffer2ndarray = require( '@stdlib/ndarray-from-arraybuffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 4
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var arraybuffer2ndarray = require( '@stdlib/ndarray-from-arraybuffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float32', buf, [ 4, 2 ], [ 2, 1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 8
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var arraybuffer2ndarray = require( '@stdlib/ndarray-from-arraybuffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2 ], [ -2, -1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 4
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var arraybuffer2ndarray = require( '@stdlib/ndarray-from-arraybuffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2 ], [ -1, -2 ], 0, 'column-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 4
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var arraybuffer2ndarray = require( '@stdlib/ndarray-from-arraybuffer' );
*
* var buf = new ArrayBuffer( 64 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 2, 2, 2 ], [ 2, -4, 1 ], 0, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 8
*
* @example
* var numel = require( '@stdlib/ndarray-numel' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var arraybuffer2ndarray = require( '@stdlib/ndarray-from-arraybuffer' );
*
* var buf = new ArrayBuffer( 32 );
* var v = arraybuffer2ndarray( 'float64', buf, [ 1, 2 ], [ -2, -1 ], 8, 'row-major' );
* // returns <ndarray>
*
* var N = numel( v );
* // returns 2
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
